import ghidra.app.decompiler.*; import ghidra.app.script.GhidraScript; import ghidra.program.model.listing.*; import ghidra.program.model.symbol.*;
public class PostTransformCallers extends GhidraScript { public void run()throws Exception{DecompInterface d=new DecompInterface();d.openProgram(currentProgram);long[] xs={0x0041a2d0L,0x00425a70L,0x004258e0L,0x00425c70L};for(long x:xs){Function t=getFunctionAt(toAddr(x));println("=== TARGET "+toAddr(x)+" "+t+" ===");Reference[] rs=getReferencesTo(t.getEntryPoint());for(Reference rr:rs){Function f=getFunctionContaining(rr.getFromAddress());if(f==null)continue;println("CALLER "+rr.getFromAddress()+" "+f.getName());DecompileResults z=d.decompileFunction(f,120,monitor);if(z.getDecompiledFunction()!=null){String c=z.getDecompiledFunction().getC();for(String l:c.split("\n"))if(l.contains("0041a2d0")||l.contains("00425a70")||l.contains("004258e0")||l.contains("00425c70")||l.contains("0x150")||l.contains("0x1d8")||l.contains("0x1e8"))println(l);}}}d.dispose();}}
